c='p9';B='PYTHON 5'
S=[]
S.append(TITLE('TIN HỌC · PYTHON 5','ĐỘ PHỨC TẠP<br>THUẬT TOÁN','Đếm phép toán, kí hiệu O, so sánh O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ).',['O(1)','O(n)','O(n²)','O(log n)']))
S.append(goals(c,B,['Hiểu <b>độ phức tạp thời gian</b> là tốc độ tăng số phép toán theo n.','Nhận biết <b>O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ)</b>.','<b>Đếm phép toán</b> trong vòng lặp đơn, lồng, chia đôi.','Ước lượng <b>thời gian chạy</b> với n = 10⁵, 10⁶, 10⁹.','Chọn thuật toán <b>phù hợp giới hạn</b> đề bài.'],['Độ phức tạp là gì','Nhận biết qua mã','Bảng so sánh tốc độ tăng','Đếm phép toán','Trọng tâm, HSG']))
S.append(S2(c,B+' · 1','Vì sao cần đo độ phức tạp?',card('Vấn đề',ul(['Một bài toán có <b>nhiều thuật toán</b>; thuật toán nào <b>nhanh hơn</b>?','Đo bằng giây phụ thuộc <b>máy, ngôn ngữ</b>.','Cần thước đo <b>độc lập máy</b>: đếm <b>số phép toán cơ bản</b> theo <b>cỡ dữ liệu n</b>.'],6)),KEY('<b>Độ phức tạp thời gian</b>: số phép toán cần thực hiện <b>tăng thế nào khi n tăng</b>, bỏ qua hằng số và số hạng bé.')+OK('Quan tâm n <b>rất lớn</b>: 3n + 100 và 5n đều coi là <b>O(n)</b>.')))
S.append(PYR(c,B+' · 1','Đếm phép toán: vòng lặp đơn','def dem(n):\n    d = 0\n    for i in range(n):\n        d += 1\n    return d\n\nfor n in [10, 100, 1000]:\n    print(n, dem(n))',KEY('Một vòng lặp chạy <b>n lần</b> → <b>O(n)</b>: n tăng gấp 10 thì số phép tăng gấp 10.'),22))
S.append(PYR(c,B+' · 1','Đếm phép toán: hai vòng lồng','def dem(n):\n    d = 0\n    for i in range(n):\n        for j in range(n):\n            d += 1\n    return d\n\nfor n in [10, 100, 1000]:\n    print(n, dem(n))',KEY('Hai vòng lồng nhau đều chạy n lần → <b>n × n = O(n²)</b>: n tăng 10 lần thì số phép tăng <b>100 lần</b>.'),22))
S.append(PYR(c,B+' · 1','Đếm phép toán: vòng lặp chia đôi','def dem(n):\n    d = 0\n    while n > 1:\n        n //= 2\n        d += 1\n    return d\n\nfor n in [8, 1024, 10**6, 10**9]:\n    print(n, dem(n))',KEY('Mỗi lần giảm một nửa → số lần lặp ≈ <b>log₂ n</b> → <b>O(log n)</b>. Với n = 10⁹ chỉ cần khoảng <b>30</b> lượt!'),22))
S.append(PYR(c,B+' · 1','Vòng lặp lồng nhưng không phải n²','def dem(n):\n    d = 0\n    for i in range(n):\n        for j in range(i):\n            d += 1\n    return d\n\nfor n in [10, 100]:\n    print(n, dem(n), n * (n - 1) // 2)',KEY('Tổng 0 + 1 + … + (n-1) = n(n-1)/2 ≈ n²/2 → vẫn là <b>O(n²)</b> (bỏ hệ số 1/2).'),22))
S.append(TB(c,B+' · 2','Các lớp độ phức tạp thường gặp',['Kí hiệu','Tên','Ví dụ'],[['<b>O(1)</b>','hằng số','truy cập <code>a[i]</code>, <code>a + b</code>'],['<b>O(log n)</b>','logarit','tìm kiếm nhị phân, chia đôi'],['<b>O(n)</b>','tuyến tính','duyệt dãy, tìm max, tìm tuần tự'],['<b>O(n log n)</b>','—','sắp xếp trộn, sort() của Python'],['<b>O(n²)</b>','bình phương','sắp xếp chọn, nổi bọt, chèn'],['<b>O(2ⁿ)</b>','mũ','duyệt mọi tập con, Fibonacci đệ quy ngây thơ']],mono=1,note=KEY('Thứ tự tăng dần: <b>1 &lt; log n &lt; n &lt; n log n &lt; n² &lt; 2ⁿ</b>.')))
S.append(S2(c,B+' · 2','Quy tắc rút gọn kí hiệu O',card('Cách rút gọn',ul(['Bỏ <b>hằng số nhân</b>: 5n → O(n).','Bỏ <b>số hạng bậc thấp</b>: n² + 3n + 7 → O(n²).','Hai đoạn <b>nối tiếp</b>: <b>cộng</b>, lấy phần lớn: O(n) + O(n²) = O(n²).','Hai vòng <b>lồng nhau</b>: <b>nhân</b>: O(n) × O(m) = O(nm).'],6)),T(tr('Phép toán','Độ phức tạp',h=True)+tr('3n + 100','O(n)',m=True)+tr('n² + n log n','O(n²)',m=True)+tr('vòng n lồng vòng log n','O(n log n)',m=True)+tr('2n + n²/2','O(n²)',m=True))))
S.append(PYR(c,B+' · 2','So sánh tốc độ tăng','import math\nprint("n        logn     n*logn      n^2")\nfor n in [10, 100, 1000, 10**6]:\n    print(n, round(math.log2(n)), round(n*math.log2(n)), n*n)',KEY('Khi n = 10⁶: <b>n log n</b> khoảng 2·10⁷ (chạy trong giây), còn <b>n²</b> = 10¹² (không thể chạy trong thời gian cho phép).'),20))
S.append(TB(c,B+' · 2','Ước lượng thời gian chạy',['n lớn nhất','Độ phức tạp chấp nhận được','Ghi chú'],[['n ≤ 10','O(n!), O(2ⁿ · n)','vét cạn, hoán vị'],['n ≤ 20–25','O(2ⁿ)','duyệt tập con'],['n ≤ 5 000','O(n²)','hai vòng lồng'],['n ≤ 10⁵','O(n log n)','sắp xếp, nhị phân'],['n ≤ 10⁶–10⁷','O(n)','duyệt một lần'],['n ≤ 10⁹ trở lên','O(log n), O(1)','công thức, chia đôi']],note=KEY('Quy ước thực tế: máy thực hiện khoảng <b>10⁷ – 10⁸ phép tính cơ bản mỗi giây</b> (Python chậm hơn, khoảng 10⁷).')))
S.append(PYR(c,B+' · 3','Tính tổng 1..n: ba cách','def c1(n):\n    s = 0\n    for i in range(1, n + 1):\n        s += i\n    return s\n\ndef c2(n):\n    return n * (n + 1) // 2\n\nprint(c1(100), c2(100))\nprint(c2(10**12))',KEY('Cách 1: <b>O(n)</b>. Cách 2 dùng công thức: <b>O(1)</b>. Với n = 10¹², cách 1 không chạy nổi, cách 2 xong tức thì.'),22))
S.append(PYR(c,B+' · 3','Số nguyên tố: thử đến n hay đến √n','def thu(n):\n    d = 0\n    i = 2\n    while i * i <= n:\n        d += 1\n        i += 1\n    return d\n\nn = 1000003\nprint("đến n-1:", n - 2)\nprint("đến √n:", thu(n))',KEY('Thử đến <b>n-1</b>: O(n) ≈ 10⁶ lượt. Thử đến <b>√n</b>: O(√n) ≈ <b>10³</b> lượt, cho cùng kết luận n = 1000003 là số nguyên tố.'),22))
S.append(PYR(c,B+' · 3','Tìm tuần tự và tìm nhị phân','def nhi_phan(a, x):\n    l, r, d = 0, len(a) - 1, 0\n    while l <= r:\n        d += 1\n        m = (l + r) // 2\n        if a[m] < x:\n            l = m + 1\n        else:\n            r = m - 1\n    return d\n\na = list(range(1, 100001))\nprint("tuần tự:", len(a))\nprint("nhị phân:", nhi_phan(a, 100000))',KEY('Trường hợp xấu nhất với 10⁵ phần tử: tuần tự <b>100 000</b> bước, nhị phân chỉ khoảng <b>17</b> bước.'),20))
S.append(S2(c,B+' · 3','Độ phức tạp theo trường hợp',T(tr('Trường hợp','Ý nghĩa','Tìm tuần tự',h=True)+tr('Tốt nhất','dữ liệu thuận lợi','x ở đầu: O(1)')+tr('Trung bình','dữ liệu ngẫu nhiên','khoảng n/2: O(n)')+tr('<b>Xấu nhất</b>','dữ liệu bất lợi nhất','x ở cuối/không có: O(n)')),KEY('Khi nói “độ phức tạp” mặc định là <b>trường hợp xấu nhất</b>, vì đó là mức <b>đảm bảo</b> không vượt quá.')+OK('Đề thi HSG thường hỏi: “Đánh giá độ phức tạp của đoạn mã sau”: đếm vòng lặp, xét xem biến lặp tăng hay giảm đều.')))
S.append(PYR(c,B+' · 3','Độ phức tạp bộ nhớ','n = 10**6\nm1 = [0] * n\nm2 = [[0] * 1000 for _ in range(1000)]\nprint(len(m1), len(m2) * len(m2[0]))',KEY('<b>Độ phức tạp không gian</b>: lượng bộ nhớ cần. Mảng n phần tử: O(n); ma trận n×n: <b>O(n²)</b>. Giới hạn bộ nhớ đề bài thường 256 MB.'),22))
S.append(PYR(c,B+' · 3','Fibonacci: O(2ⁿ) và O(n)','def fib1(n):\n    global dem\n    dem += 1\n    return n if n < 2 else fib1(n - 1) + fib1(n - 2)\n\ndem = 0\nprint(fib1(20), dem)\n\ndef fib2(n):\n    a, b = 0, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\nprint(fib2(20), fib2(90))',KEY('Đệ quy ngây thơ gọi <b>21 891</b> lần cho n = 20 (tăng gần 1,6ⁿ); vòng lặp chỉ <b>n</b> bước.'),19))
S+=END(c,B,['Độ phức tạp = tốc độ tăng số phép toán theo <b>n</b>; bỏ hằng số và số hạng bé.','Vòng đơn <b>O(n)</b>; lồng nhau <b>O(n²)</b>; chia đôi <b>O(log n)</b>.','Thứ tự: <b>1 &lt; log n &lt; n &lt; n log n &lt; n² &lt; 2ⁿ</b>.','Nối tiếp thì <b>cộng</b> (lấy lớn), lồng nhau thì <b>nhân</b>.','Máy làm khoảng <b>10⁸</b> phép/giây: chọn thuật toán theo giới hạn n.'],[('n ≤ 10⁵','O(n log n)'),('n ≤ 10⁶','O(n)'),('n ≤ 5000','O(n²)'),('n ≤ 25','O(2ⁿ)')],'Không bỏ qua vòng lặp ẩn: <code>in</code> trên list, <code>sum</code>, <code>.index</code> đều là O(n).',['<code>x in list</code> là <b>O(n)</b> nhưng <code>x in set</code> là <b>O(1)</b> (trung bình).','<code>a.append</code> O(1) nhưng <code>a.insert(0, x)</code> <b>O(n)</b>.','<code>sorted</code> là <b>O(n log n)</b>.','Cắt lát <code>a[i:j]</code> tốn <b>O(j-i)</b>.'],['<b>Ω, Θ</b>: cận dưới và cận chặt (mở rộng).','<b>Độ phức tạp trung bình</b> khác xấu nhất (Quick sort).','<b>Đánh đổi thời gian và bộ nhớ</b> (bảng băm, bảng tính trước).'],
 [('Đánh giá độ phức tạp: <code>for i in range(n): s += i</code>.',),('Đánh giá: <code>for i in range(n): for j in range(n): pass</code>.',),('Đánh giá: <code>while n &gt; 0: n //= 10</code> (n có k chữ số).',),('Đánh giá: <code>for i in range(n): for j in range(5): pass</code>.',),('Rút gọn: <code>5n² + 3n log n + 100</code>.',)],
 [('<b>O(n)</b>.',),('<b>O(n²)</b>.',),('<b>O(k)</b> = O(log₁₀ n) (mỗi lần bớt một chữ số).',),('<b>O(5n) = O(n)</b>.',),('<b>O(n²)</b>.',)],
 [('Đánh giá độ phức tạp:',"for i in range(1, n):\n    j = 1\n    while j < n:\n        j *= 2"),
  ('Đánh giá độ phức tạp:',"for i in range(n):\n    for j in range(i, n):\n        for k in range(3):\n            pass"),
  ('Một thuật toán O(n²) mất 1 giây với n = 10⁴. Ước lượng thời gian với n = 10⁵.',),
  ('Một thuật toán O(n log n) mất 1 giây với n = 10⁵. Ước lượng với n = 10⁶ (xấp xỉ).',),
  ('Đúng hay sai: (a) O(n) luôn nhanh hơn O(n²). (b) <code>x in set</code> nhanh hơn <code>x in list</code> khi dữ liệu lớn. (c) 3n + 1000 là O(n). (d) Hằng số nhân bị bỏ nên 1000n tốt hơn n².',),
  ('Cho n = 10⁶: nên chọn thuật toán O(n²), O(n log n) hay O(n)? Vì sao?',)],
 [('Vòng ngoài n lần, vòng trong log n lần → <b>O(n log n)</b>.',),('Ba vòng lồng nhưng vòng trong cùng chạy hằng số (3): <b>O(n²)</b>.',),('Tăng n lên 10 lần → thời gian tăng 10² = 100 lần: khoảng <b>100 giây</b>.',),('Khoảng 10 × (20/17) ≈ <b>11–12 giây</b> (n tăng 10 lần, log n tăng nhẹ).',),('(a) <b>Sai</b> với n nhỏ hoặc hằng số lớn. (b) <b>Đúng</b>. (c) <b>Đúng</b>. (d) <b>Sai</b>: với n &lt; 1000 thì n² còn nhỏ hơn 1000n; kí hiệu O chỉ nói về n rất lớn.',),('Với 10⁶: O(n²) = 10¹² (quá chậm), O(n log n) ≈ 2·10⁷ (được), O(n) tốt nhất. Chọn <b>O(n) hoặc O(n log n)</b>.',)],hper=2)
